/* =====================================================================
   Photographed material tiles

   The half of a surface that code cannot fake. Traces, silkscreen and
   labels are better GENERATED, because they can be derived from the ticket
   — a drive label shows the capacity this ticket dealt. Material grain is
   the opposite: it is irregular in a way that reads as fake the moment it
   is generated, and five attempts at generating it all aliased. Point noise
   does not minify; sub-pixel specks turn into crawling static the moment
   the camera pulls back. A photograph settles it.

   Each tile is prepared before it gets here: cropped square, resized to
   512, and made to repeat WITHOUT A SEAM by an offset blend — roll the
   image by half so each copy's wrapping seam lands in the middle of the
   other, then blend across the edges. Mirroring is also seamless and it is
   unusable: it produces a kaleidoscope that any feature larger than a few
   pixels gives away instantly.

   Provenance is recorded per tile and it is not decoration. These are
   embedded in something students download.
   ===================================================================== */
export const TILES = {
  dust: {
    /* The one FAULT texture in the set, and the surface students are asked
       to recognise more often than any other: a fin stack felted solid.
       Supplied by the author of this build. */
    credit: "Supplied by the build owner, used with permission",
    look: "The mat is continuous across the fins rather than sitting in " +
      "clumps between them, and the fin edges are only visible in glimpses. " +
      "Air cannot cross that.",
    src: "data:image/jpeg;base64,"
  }
};

/* The tile for a surface name, or null when that surface is generated. */
export function tileFor(name) {
  return (name && TILES[name]) || null;
}

/* Load-time check, in the same spirit as photos.js. A tile filed under a
   name no painter knows would simply never be drawn, and nobody would find
   out — the failure mode of every keyed table in this build. */
Object.keys(TILES).forEach(function (k) {
  var t = TILES[k];
  if (!t.src || t.src.indexOf("data:image/") !== 0) {
    throw new Error('tiles: "' + k + '" has no embedded image. It must be a ' +
      "data: URI, because this build fetches nothing.");
  }
  if (!t.credit) {
    throw new Error('tiles: "' + k + '" has no credit. A photograph embedded ' +
      "in something students download needs its provenance recorded.");
  }
  if (!t.look) {
    throw new Error('tiles: "' + k + '" has no "look" line.');
  }
});
